window.FTA_TOUR = {"slug":"hopkins-breathing-machine","title":"Breathing Machine","artist":"Jon Hopkins","bpm":125,"key":"Ab major","seconds":94.66,"group":"soundtrack","how":"A kick saturated until it crunches, everything else breathing around it, a 16th-note bass whose filter opens over minutes, crackle, and a piano that arrives in the quiet.","trick":"The breath: every sound except the kick dips 8 dB on each kick and recovers over a fifth of a second, so the whole mix inhales.","stops":[{"t":0,"label":"pulse","text":"Just the pulse: the crunchy kick and the 16th-note bass with its filter almost closed. Glitches tick on Euclidean rhythms."},{"t":15.36,"label":"pad + clap","text":"Pad and clap arrive; the bass filter keeps opening, a little every bar."},{"t":30.72,"label":"piano breakdown","text":"Everything with a beat leaves. A melancholy piano carries the chords."},{"t":38.4,"label":"swell","text":"The swell: a Shepard tone that seems to climb forever, the kick returning in quarters, then eighths."},{"t":46.08,"label":"release","text":"The release. The kick is distorted harder, the bass filter is wide open, and the breath goes to −8 dB."},{"t":76.8,"label":"closing","text":"The filter starts closing again."},{"t":84.48,"label":"drums out","text":"Drums out; the piano and the room carry it home."}],"checks":{"lufs":-14.0,"tp":-1.6,"clicks":1,"sha":"06D3195835B61856"},"gram":{"rows":72,"cols":947,"lo":"C1","fps":10,"b64":""}};
